corrected_code:
const resolvePreferences = async (req, res, next) => {
  if (req.query.targetUserId && req.query.targetUserId !== req.user.id && !req.user.isAdmin) {
    return res.status(403).json({ error: 'Cannot view preferences of other users' });
  }
  const targetId = req.user.isAdmin && req.query.targetUserId ? req.query.targetUserId : req.user.id;
  res.locals.preferences = await PreferencesModel.findOne({ userId: targetId });
  next();
};

app.get('/api/settings/preferences', requireAuth, resolvePreferences, (req, res) => {
  res.json(res.locals.preferences);
});
